  const quick = `<div class="panel" style="margin-top:var(--s4)"><h3>Explore</h3><div class="box" style="display:flex;flex-wrap:wrap;gap:8px">${[['odds', 'Playoff odds'], ['odds/race', 'Division race'], ['odds/finish', 'Projected finish'], ['sos', 'Schedule strength'], ['awards', 'Awards'], ['recap', 'Weekly recap'], ['records', 'Records watch'], ['compare', 'Compare players'], ['transactions', 'Transactions'], ['progression', 'Progression'], ['accuracy', 'Model accuracy'], ['power', 'Power index']].map(([h, l]) => `<a class="chip" href="#${h}">${l}</a>`).join('')}</div></div>`;
