  const roster = Object.values(L.players).filter(p => p.tid == id); const games = Object.values(L.games).filter(g => g.si === si && (g.homeTeamId == id || g.awayTeamId == id)).sort((a, b) => (a.stage === 'pre' ? -1 : 0) - (b.stage === 'pre' ? -1 : 0) || a.wi - b.wi);
