async function odds(tab = 'playoffs') {
  const si = seasonSel(); const S = simSeason(si); const R = records(si); const P = power(si); const rt = {}; P.forEach(x => rt[x.id] = x.rating);
  const tabs = [['playoffs', 'Playoff odds'], ['race', 'Division race'], ['finish', 'Projected finish']];
  view.innerHTML = `<div class="bar"><div><h1>Playoff odds</h1><h2>${esc(seasonLabel(si))} · ${S._done ? 'regular season complete' : `rest of the season simulated ${S._N || 1500} times from the power index`}</h2></div>${seasonPicker(si)}</div>
    <div class="tabs">${tabs.map(([k, l]) => `<button class="${k === tab ? 'on' : ''}" data-tab="${k}">${l}</button>`).join('')}</div><div id="otab"></div>${simNote(S)}`;
  view.querySelectorAll('[data-tab]').forEach(b => b.onclick = () => { history.replaceState(null, '', '#odds/' + b.dataset.tab); odds(b.dataset.tab); });
  const el = document.getElementById('otab'); const ids = Object.keys(L.teams);
  if (tab === 'playoffs') {
    el.innerHTML = ['AFC', 'NFC'].map(c => { const rows = ids.filter(id => team(id).conf === c).sort((a, b) => S[b].po - S[a].po || S[b].w - S[a].w); if (!rows.length) return '';
      return `<div class="panel"><h3>${c}</h3><div class="tw"><table class="stats"><thead><tr><th>Team</th><th class="num">Record</th><th class="num">Proj W-L</th><th class="num">Div</th><th class="num">Playoffs</th><th class="num">Bye</th><th class="num">Conf</th><th class="num">Super Bowl</th></tr></thead><tbody>${rows.map(id => { const o = S[id], t = team(id); const cell = p => `<td class="num ${p >= .995 ? 'pos' : p < .005 ? 'muted' : ''}">${pct(p, S._done)}</td>`; return `<tr class="clk ${t.user ? 'fav' : ''}" data-t="${esc(id)}"><td class="tm">${tLogo(t, 24)}${esc(t.name)}</td><td class="num">${esc(R[id].rec)}</td><td class="num">${o.w.toFixed(1)}-${(GP_SEASON - o.w).toFixed(1)}</td>${cell(o.div)}${cell(o.po)}${cell(o.bye)}${cell(o.conf)}${cell(o.sb)}</tr>`; }).join('')}</tbody></table></div></div>`; }).join('') || '<div class="panel"><div class="empty">Teams need AFC/NFC divisions for playoff odds. Export League Info.</div></div>';
  } else if (tab === 'race') {
    const divs = [...new Set(ids.map(id => team(id).div).filter(Boolean))].sort();
    el.innerHTML = `<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(440px,1fr))">${divs.map(d => { const rows = ids.filter(id => team(id).div === d).sort((a, b) => R[b].pct - R[a].pct || (R[b].pf - R[b].pa) - (R[a].pf - R[a].pa)); const lead = R[rows[0]];
      return `<div class="panel"><h3>${esc(d)}</h3><div class="tw"><table class="stats"><thead><tr><th>Team</th><th class="num">W-L</th><th class="num">GB</th><th class="num">Div rec</th><th class="num">Left</th><th class="num">Rem. SOS</th><th class="num">Div odds</th></tr></thead><tbody>${rows.map((id, i) => { const r = R[id], t = team(id), o = S[id]; const gb = ((lead.w - r.w) + (r.l - lead.l)) / 2; const left = regGames(si, id).filter(g => !g.played); const sos = left.length ? left.reduce((s, g) => s + (rt[g.homeTeamId == id ? g.awayTeamId : g.homeTeamId] ?? 0), 0) / left.length : null; const magic = i === 0 && rows[1] ? GP_SEASON + 1 - r.w - R[rows[1]].l : null; const maxW = x => R[x].w + GP_SEASON - R[x].g; const clinched = i === 0 && rows[1] && r.w > maxW(rows[1]); const out = i > 0 && maxW(id) < lead.w;
        return `<tr class="clk ${t.user ? 'fav' : ''}" data-t="${esc(id)}"><td class="tm">${tLogo(t, 22)}${esc(t.abbr)}${clinched ? ' <span class="tag ok">clinched</span>' : out ? ' <span class="tag out">out</span>' : ''}</td><td class="num">${esc(r.rec)}</td><td class="num">${gb ? gb : '–'}${magic != null && magic > 0 && magic <= GP_SEASON ? ` <small class="muted" title="magic number">M${magic}</small>` : ''}</td><td class="num">${split(r.div)}</td><td class="num">${left.length + o.missing}</td><td class="num">${sos == null ? '–' : sgn(sos.toFixed(1))}</td><td class="num ${o.div >= .995 ? 'pos' : ''}"><b>${pct(o.div, S._done)}</b></td></tr>`; }).join('')}</tbody></table></div></div>`; }).join('')}</div><p class="note">GB is games back of the division leader. M is the magic number: any combination of leader wins and runner-up losses that adds up to it clinches the division. Rem. SOS is the average power rating of the opponents still on the exported schedule.</p>`;
  } else {
    const rows = ids.sort((a, b) => S[b].w - S[a].w); const hi = Math.max(...rows.map(id => Math.max(...S[id].dist)));
    el.innerHTML = `<div class="panel"><div class="tw"><table class="stats"><thead><tr><th>#</th><th>Team</th><th class="num">Now</th><th class="num">Proj W-L</th><th class="num">Win distribution (0–17)</th><th class="num">≥ 10 wins</th><th class="num">≥ 13 wins</th><th class="num">Power</th></tr></thead><tbody>${rows.map((id, i) => { const o = S[id], t = team(id); const atLeast = n => o.dist.slice(n).reduce((s, p) => s + p, 0); return `<tr class="clk ${t.user ? 'fav' : ''}" data-t="${esc(id)}"><td class="num muted">${i + 1}</td><td class="tm">${tLogo(t, 22)}${esc(t.name)}</td><td class="num">${esc(R[id].rec)}</td><td class="num"><b>${o.w.toFixed(1)}-${(GP_SEASON - o.w).toFixed(1)}</b></td><td class="num">${distBars(o, hi)}</td><td class="num">${pct(atLeast(10), S._done)}</td><td class="num">${pct(atLeast(13), S._done)}</td><td class="num ${rt[id] >= 0 ? 'pos' : 'neg'}">${sgn((rt[id] || 0).toFixed(1))}</td></tr>`; }).join('')}</tbody></table></div></div><p class="note">Each simulated game is decided by the two teams' power ratings plus 2 points for the home team, with normal game-to-game noise. Hover a distribution for the chance of each win total.</p>`;
  }
  wire(); bindSeason();
}

async function sos() {
  const si = seasonSel(); const P = power(si); const rt = {}; P.forEach(x => rt[x.id] = x.rating); const R = records(si); const S = simSeason(si);
  const rows = Object.keys(L.teams).map(id => { const gs = regGames(si, id); const opp = g => g.homeTeamId == id ? g.awayTeamId : g.homeTeamId; const played = gs.filter(g => g.played), left = gs.filter(g => !g.played).sort((a, b) => a.wi - b.wi); const avg = a => a.length ? a.reduce((s, g) => s + (rt[opp(g)] ?? 0), 0) / a.length : null; const oppPct = played.length ? played.reduce((s, g) => s + (R[opp(g)]?.pct || 0), 0) / played.length : 0;
    const hardest = left.slice().sort((a, b) => (rt[opp(b)] ?? 0) - (rt[opp(a)] ?? 0))[0]; return { id, t: team(id), R: R[id], past: avg(played), rem: avg(left), oppPct, left, hardest, nleft: left.length + S[id].missing, next: left.slice(0, 3).map(g => ({ g, o: team(opp(g)), home: g.homeTeamId == id, p: g.homeTeamId == id ? pwinOf(rt[id], rt[opp(g)]) : 1 - pwinOf(rt[opp(g)], rt[id]) })) }; });
  view.innerHTML = `<div class="bar"><div><h1>Schedule strength</h1><h2>${esc(seasonLabel(si))} · average power rating of opponents, played and remaining</h2></div>${seasonPicker(si)}</div>
    <div class="panel"><div class="tw"><table id="sost" class="stats"><thead><tr><th>Team</th><th class="num sort" data-k="pct">Record</th><th class="num sort" data-k="past">Played SOS</th><th class="num sort" data-k="opp">Opp win%</th><th class="num sort" data-k="rem">Remaining SOS</th><th class="num sort" data-k="left" data-asc="1">Left</th><th>Hardest left</th><th>Next 3 (win chance)</th></tr></thead><tbody></tbody></table></div></div>${simNote(S)}<p class="note">Positive means tougher than average opponents. Remaining SOS only counts weeks whose schedule has been exported.</p>`;
  sortTable(document.getElementById('sost'), rows, { pct: r => r.R.pct, past: r => r.past ?? -99, opp: r => r.oppPct, rem: r => r.rem ?? -99, left: r => r.nleft }, r => `<tr class="clk ${r.t.user ? 'fav' : ''}" data-t="${esc(r.id)}"><td class="tm">${tLogo(r.t, 24)}${esc(r.t.name)}</td><td class="num">${esc(r.R.rec)}</td><td class="num">${r.past == null ? '–' : sgn(r.past.toFixed(1))}</td><td class="num">${pct3(r.oppPct)}</td><td class="num ${r.rem > 2 ? 'neg' : r.rem < -2 ? 'pos' : ''}">${r.rem == null ? '–' : sgn(r.rem.toFixed(1))}</td><td class="num">${r.nleft}</td><td>${r.hardest ? `<span class="tmi">${tLogo(team(r.hardest.homeTeamId == r.id ? r.hardest.awayTeamId : r.hardest.homeTeamId), 20)}${r.hardest.homeTeamId == r.id ? 'vs' : '@'} ${esc(team(r.hardest.homeTeamId == r.id ? r.hardest.awayTeamId : r.hardest.homeTeamId).abbr)} <small class="muted">${esc(weekShort(r.hardest.stage, r.hardest.wi))}</small></span>` : '<span class="muted">–</span>'}</td><td>${r.next.map(n => `<span class="nchip" title="${esc(weekLabel(n.g.stage, n.g.wi))}">${n.home ? 'vs' : '@'} ${esc(n.o.abbr)} <b class="${n.p >= .5 ? 'pos' : 'neg'}">${Math.round(n.p * 100)}%</b></span>`).join(' ') || '<span class="muted">–</span>'}</td></tr>`, 'rem', -1);
  bindSeason();
}

