  const metric = (label, get, asc, fmt = v => v.toFixed(1)) => { const vals = {}; ids.forEach(i => { const v = get(i); if (v != null) vals[i] = v; }); const v = vals[id]; if (!Object.values(vals).some(x => x)) return ''; return v == null ? '' : `<div class="kpi"><small>${label}</small><b>${fmt(v)}${rkTag(rankOf(vals, id, asc), Object.keys(vals).length)}</b></div>`; };
