  const games = regGames(si, id).filter(g => g.played).sort((a, b) => a.wi - b.wi); const pfw = games.map(g => num(g.homeTeamId == id ? g.homeScore : g.awayScore)), paw = games.map(g => num(g.homeTeamId == id ? g.awayScore : g.homeScore)); const labels = games.map(g => weekShort(g.stage, g.wi));
